xpath.script:
(function () {
    var key = "tc_lead:" + location.pathname + location.search;
    try { if (sessionStorage.getItem(key)) { return; } sessionStorage.setItem(key, "1"); } catch (e) { /* storage blocked: still count */ }
    window.dataLayer = window.dataLayer || [];
    window.gtag = window.gtag || function () { window.dataLayer.push(arguments); };
    window.gtag("event", "generate_lead", { currency: "USD", lead_source: "quote_form", site: "Tooling Components" });
})();
